// 1. Grab what the customer typed (names match the left panel)
const name  = $json['Name'] || '';
const phone = $json['Phone'] || '';
const size  = $json['Lawn size (sq ft)'] || '';

// 2. Fix capitals: "mike o'brien" becomes "Mike O'Brien"
const cleanName = name.trim().toLowerCase().replace(/\s+/g, ' ')
  .replace(/(^|[\s'-])\S/g, c => c.toUpperCase());

// 3. Keep the digits, then format: (301) 555-0142
const d = phone.replace(/\D/g, '').slice(-10);
const cleanPhone = d.length === 10 ? `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}` : phone;

// 4. Turn "6,500 sq ft" into the number 6500
const sqft = Number(String(size).replace(/[^0-9.]/g, '')) || 0;

// 5. Hand the clean fields to the next node
return { json: { name: cleanName, phone: cleanPhone, sqft } };

// Your prices: the only two numbers you change
const basePerMow = 45;   // dollars per visit
const per1000    = 4;    // extra dollars per 1,000 sq ft

const perMow = Math.round(basePerMow + ($json.sqft / 1000) * per1000);
const season = perMow * 26;   // weekly mows, April to September

// Keep everything from Clean Up, add the price
return { json: { ...$json, perMow, season, seasonText: '$' + season.toLocaleString('en-US') } };
